import React, { useState, useEffect, useRef } from 'react';
import { Heart, MessageCircle, Share2, Plus, Salad, Pizza, Search, Leaf, Flame, X, ChefHat, Utensils, PartyPopper, Cookie, Sandwich, Globe, MapPin, Camera, Image as ImageIcon, Aperture, Send, ChevronDown, MoreHorizontal, Map as MapIcon, User, Star, Navigation, TrendingUp, Bookmark, Folder, ArrowLeft, Bell } from 'lucide-react';

// --- DADOS E CONFIGURAÇÕES ---
const tagsConfig = [
  { id: 'todos', label: 'Todos', icon: null },
  { id: 'diy', label: 'DIY (Caseiro)', icon: <ChefHat className="w-3 h-3" /> },
  { id: 'restaurante', label: 'Restaurante', icon: <Utensils className="w-3 h-3" /> },
  { id: 'banquete', label: 'Banquete', icon: <PartyPopper className="w-3 h-3" /> },
  { id: 'doce', label: 'Doce', icon: <Cookie className="w-3 h-3" /> },
  { id: 'salgado', label: 'Salgado', icon: <Sandwich className="w-3 h-3" /> },
];

const locationsConfig = [
  { id: 'mundo', label: 'Mundo', icon: <Globe className="w-4 h-4"/> },
  { id: 'pais', label: 'Meu País', icon: <MapIcon className="w-4 h-4"/> },
  { id: 'cidade', label: 'Minha Cidade', icon: <MapPin className="w-4 h-4"/> },
];

const INITIAL_POSTS = [
    { id: 1, user: "Julia_FitLife", avatar: "https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=100", images: ["https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=800", "https://images.unsplash.com/photo-1540189549336-e6e99c3679fe?auto=format&fit=crop&w=800"], description: "Salada colorida para o almoço! 🥗", likes: 124, category: 'fit', tags: ['diy', 'salgado'], location: 'cidade', time: "2h", isLiked: false, showComments: false, commentsList: [{id: 101, user: "Fit_Guy", text: "Que delícia!", likes: 10, isLiked: false, replies: []}, {id: 102, user: "Ana_S", text: "Receita?", likes: 5, isLiked: false, replies: []}] },
    { id: 2, user: "Burger_Fan", avatar: "https://images.unsplash.com/photo-1535713875002-d1d0cf377fde?auto=format&fit=crop&w=100", images: ["https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=800"], description: "Hambúrguer artesanal! 🍔", likes: 89, category: 'fun', tags: ['restaurante', 'salgado'], location: 'mundo', time: "4h", isLiked: false, showComments: false, commentsList: [] },
    { id: 3, user: "Chef_Ana", avatar: "https://images.unsplash.com/photo-1580489944761-15a19d654956?auto=format&fit=crop&w=100", images: ["https://images.unsplash.com/photo-1565958011703-44f9829ba187?auto=format&fit=crop&w=800"], description: "Bolo de morango feito em casa 🍰", likes: 230, category: 'fun', tags: ['diy', 'doce'], location: 'cidade', time: "5h", isLiked: false, showComments: false, commentsList: [] },
];

// --- COMPONENTE SWIPEABLE MODAL ---
const SwipeableModal = ({ children, isOpen, onClose }) => {
    const modalRef = useRef(null);
    const contentRef = useRef(null);
    const dragRef = useRef({ startY: 0, currentY: 0, isDragging: false });

    useEffect(() => {
        if (isOpen) {
            document.body.style.overflow = 'hidden';
            if (modalRef.current) modalRef.current.style.transform = 'translateY(0)';
        } else {
            document.body.style.overflow = '';
        }
        return () => { document.body.style.overflow = ''; };
    }, [isOpen]);

    if (!isOpen) return null;

    const handleTouchStart = (e) => {
        if (contentRef.current && contentRef.current.scrollTop > 0) return;
        dragRef.current.startY = e.touches[0].clientY;
        dragRef.current.isDragging = true;
        dragRef.current.currentY = 0;
        if(modalRef.current) modalRef.current.style.transition = 'none';
    };

    const handleTouchMove = (e) => {
        if (!dragRef.current.isDragging) return;
        if (contentRef.current && contentRef.current.scrollTop > 0) {
            dragRef.current.isDragging = false;
            if (modalRef.current) modalRef.current.style.transform = 'translateY(0)';
            return;
        }
        const diff = e.touches[0].clientY - dragRef.current.startY;
        if (diff < 0) return; 
        if (e.cancelable) e.preventDefault();
        dragRef.current.currentY = diff;
        if (modalRef.current) modalRef.current.style.transform = `translateY(${diff}px)`;
    };

    const handleTouchEnd = () => {
        if (!dragRef.current.isDragging) return;
        dragRef.current.isDragging = false;
        if (modalRef.current) modalRef.current.style.transition = 'transform 0.3s cubic-bezier(0.2, 0.8, 0.2, 1)';
        if (dragRef.current.currentY > 120) {
            if(modalRef.current) modalRef.current.style.transform = `translateY(100%)`;
            setTimeout(onClose, 250);
        } else {
            if(modalRef.current) modalRef.current.style.transform = `translateY(0)`;
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-end justify-center">
            <div className="absolute inset-0 bg-black/60 backdrop-blur-sm transition-opacity" onClick={onClose}/>
            <div ref={modalRef} className="bg-white w-full max-w-md rounded-t-[32px] h-[90vh] flex flex-col relative z-10 shadow-2xl overflow-hidden will-change-transform animate-slide-up">
                <div className="w-full pt-3 pb-1 flex justify-center flex-shrink-0 touch-none z-20 bg-white cursor-grab active:cursor-grabbing" onTouchStart={handleTouchStart} onTouchMove={handleTouchMove} onTouchEnd={handleTouchEnd}>
                    <div className="w-12 h-1.5 bg-gray-300/50 rounded-full"/>
                </div>
                <div ref={contentRef} className="flex-1 overflow-y-auto overscroll-contain flex flex-col" onTouchStart={handleTouchStart} onTouchMove={handleTouchMove} onTouchEnd={handleTouchEnd}>
                    {children}
                </div>
            </div>
        </div>
    );
};

// --- CARROSSEL ---
const CarouselImage = ({ post, imageIndex, setImageIndex, onDoubleTap, showLikeAnim }) => {
  const images = post.images || [];
  const multi = images.length > 1;
  const containerRef = useRef(null);
  const touchRef = useRef({ startX: 0, startY: 0, width: 0, isDragging: false, isScrolling: false });

  useEffect(() => {
    if (containerRef.current) touchRef.current.width = containerRef.current.offsetWidth;
  }, []);

  useEffect(() => {
    if (containerRef.current) {
        containerRef.current.style.transition = 'transform 0.3s cubic-bezier(0.2, 0.8, 0.2, 1)';
        containerRef.current.style.transform = `translateX(-${imageIndex * 100}%)`;
    }
  }, [imageIndex]);

  const handleStart = (e) => {
    if (multi) {
      e.stopPropagation(); 
      touchRef.current.startX = e.touches[0].clientX;
      touchRef.current.startY = e.touches[0].clientY;
      touchRef.current.isDragging = false;
      touchRef.current.isScrolling = false;
      touchRef.current.width = e.currentTarget.offsetWidth;
      if (containerRef.current) containerRef.current.style.transition = 'none';
    }
  };

  const handleMove = (e) => {
    if (!multi || touchRef.current.isScrolling) return;

    e.stopPropagation();
    const x = e.touches[0].clientX;
    const y = e.touches[0].clientY;
    const diffX = x - touchRef.current.startX;
    const diffY = y - touchRef.current.startY;

    // Check if user is scrolling vertically first
    if (!touchRef.current.isDragging && Math.abs(diffY) > Math.abs(diffX)) {
        touchRef.current.isScrolling = true;
        return;
    }

    if (!touchRef.current.isDragging && Math.abs(diffX) > 5) touchRef.current.isDragging = true;

    if (touchRef.current.isDragging) {
        if (e.cancelable) e.preventDefault();
        const currentOffset = -(imageIndex * 100);
        const percent = (diffX / touchRef.current.width) * 100;
        let effectivePercent = percent;
        if ((imageIndex === 0 && diffX > 0) || (imageIndex === images.length - 1 && diffX < 0)) {
            effectivePercent = percent * 0.2; 
        }
        if (containerRef.current) containerRef.current.style.transform = `translateX(${currentOffset + effectivePercent}%)`;
    }
  };

  const handleEnd = (e) => {
    if (!multi) return;
    e.stopPropagation();

    if (touchRef.current.isScrolling) {
        touchRef.current.isScrolling = false;
        return;
    }

    if (!touchRef.current.isDragging) {
        if (containerRef.current) {
             containerRef.current.style.transition = 'transform 0.3s ease';
             containerRef.current.style.transform = `translateX(-${imageIndex * 100}%)`;
        }
        return;
    }
    const diffX = e.changedTouches[0].clientX - touchRef.current.startX;
    const threshold = touchRef.current.width * 0.20;
    let newIndex = imageIndex;
    if (diffX < -threshold && imageIndex < images.length - 1) newIndex = imageIndex + 1;
    else if (diffX > threshold && imageIndex > 0) newIndex = imageIndex - 1;
    setImageIndex(newIndex);
    if (containerRef.current) {
        containerRef.current.style.transition = 'transform 0.3s cubic-bezier(0.2, 0.8, 0.2, 1)';
        containerRef.current.style.transform = `translateX(-${newIndex * 100}%)`;
    }
    touchRef.current.isDragging = false;
  };

  if (!images || images.length === 0) return <div className="aspect-square bg-gray-200" />;

  return (
    <div 
      className={`relative aspect-square bg-gray-100 select-none overflow-hidden touch-pan-y ${multi ? 'cursor-grab carousel-no-swipe' : ''}`}
      onDoubleClick={() => onDoubleTap && onDoubleTap(post.id)}
      onTouchStart={handleStart}
      onTouchMove={handleMove}
      onTouchEnd={handleEnd}
    >
      <div ref={containerRef} className="flex h-full w-full will-change-transform">
        {images.map((img, i) => (
            <div key={i} className="relative h-full min-w-full flex-shrink-0 w-full">
                <img src={img} className="w-full h-full object-cover pointer-events-none select-none" alt=""/>
            </div>
        ))}
      </div>
      {multi && <div className="absolute top-3 right-3 bg-black/60 backdrop-blur-md px-2.5 py-1 rounded-full text-[10px] font-bold text-white z-10 pointer-events-none">{imageIndex + 1}/{images.length}</div>}
      {multi && <div className="absolute bottom-4 w-full flex justify-center gap-1.5 pointer-events-none z-10">{images.map((_, i) => (<div key={i} className={`h-1.5 rounded-full transition-all duration-300 shadow-sm ${i===imageIndex ? 'w-4 bg-white' : 'w-1.5 bg-white/60'}`}/>))}</div>}
      {showLikeAnim && <div className="absolute inset-0 flex items-center justify-center animate-ping-short pointer-events-none z-20"><Heart className="w-24 h-24 text-white fill-white drop-shadow-xl"/></div>}
    </div>
  );
};

// --- POST ITEM ---
const PostItem = ({ post, activeTab, imageIndex, setImageIndex, onLike, onDoubleTap, openComments, openSave, showLikeAnim, isSaved }) => {
  const badgeColor = activeTab === 'fit' ? 'bg-green-50 text-green-700 border-green-100' : 'bg-orange-50 text-orange-700 border-orange-100';
  const locLabel = (locationsConfig.find(l => l.id === post.location)?.label || "Mundo");
  const topComments = [...(post.commentsList || [])].sort((a,b) => b.likes - a.likes).slice(0, 2);

  return (
    <article className="bg-white md:rounded-2xl shadow-sm border-b md:border border-gray-100 overflow-hidden mb-3">
      <div className="px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-2.5">
          <div className={`w-10 h-10 rounded-full p-[2px] border bg-white ${post.category==='fit'?'border-green-400':'border-orange-400'}`}>
            <img src={post.avatar} alt={post.user} className="w-full h-full rounded-full object-cover"/>
          </div>
          <div className="flex flex-col">
            <h3 className="font-bold text-gray-900 text-sm leading-none mb-1 font-brand">{post.user}</h3>
            <span className="text-[11px] text-gray-500 flex items-center gap-1 font-medium leading-none">
                {post.location === 'mundo' ? <Globe className="w-3 h-3"/> : <MapPin className="w-3 h-3"/>} 
                {locLabel} • {post.time}
            </span>
          </div>
        </div>
        <MoreHorizontal className="w-6 h-6 text-gray-400"/>
      </div>
      <CarouselImage post={post} imageIndex={imageIndex} setImageIndex={setImageIndex} onDoubleTap={onDoubleTap} showLikeAnim={showLikeAnim}/>
      <div className="p-4 pb-4">
        <div className="flex items-center gap-5 mb-3">
          <button onClick={() => onLike(post.id)} className="active:scale-90 transition-transform"><Heart className={`w-7 h-7 transition-colors ${post.isLiked?'text-red-500 fill-red-500':'text-gray-900 stroke-[1.5]'}`}/></button>
          <button onClick={() => openComments(post.id)} className="active:scale-90 transition-transform"><MessageCircle className="w-7 h-7 stroke-[1.5] text-gray-900"/></button>
          <button className="active:scale-90 transition-transform"><Share2 className="w-6 h-6 text-gray-900 stroke-[1.5]"/></button>
          <button onClick={() => openSave(post.id)} className="ml-auto active:scale-90 transition-transform"><Bookmark className={`w-6 h-6 stroke-[1.5] ${isSaved ? 'fill-black text-black' : 'text-gray-900'}`}/></button>
        </div>
        <div className="flex flex-wrap gap-1.5 mb-2.5">
           {(post.tags || []).map(tagId => {
              const t = tagsConfig.find(x=>x.id===tagId);
              return t ? <span key={tagId} className={`px-2 py-0.5 rounded-md text-[10px] font-bold uppercase tracking-wide border flex items-center gap-1 ${badgeColor}`}>{t.icon} {t.label}</span> : null
           })}
        </div>
        <div className="mb-2 text-sm text-gray-800 leading-snug">
            <span className="font-bold mr-2 font-brand">{post.user}</span>
            {post.description}
        </div>
        {topComments.length > 0 && (
            <div className="mt-2 space-y-1">
                {topComments.map(c => (
                    <div key={c.id} className="text-xs text-gray-600 cursor-pointer" onClick={() => openComments(post.id)}>
                        <span className="font-bold text-gray-900 mr-1">{c.user}</span>
                        {c.text}
                    </div>
                ))}
            </div>
        )}
        {(post.commentsList || []).length > 2 && (
            <button onClick={() => openComments(post.id)} className="text-xs text-gray-400 mt-2 font-medium">
                Ver todos os {(post.commentsList || []).length} comentários
            </button>
        )}
      </div>
    </article>
  );
};

// --- MAIN APP ---
const App = () => {
  const [posts, setPosts] = useState(() => {
      try {
        const saved = typeof window !== 'undefined' ? localStorage.getItem('foome_posts_v7') : null;
        const parsed = saved ? JSON.parse(saved) : null;
        return Array.isArray(parsed) ? parsed : INITIAL_POSTS;
      } catch (e) { return INITIAL_POSTS; }
  });
  const [savedPosts, setSavedPosts] = useState(() => { 
      try {
        const saved = typeof window !== 'undefined' ? localStorage.getItem('foome_saved_v7') : null;
        const parsed = saved ? JSON.parse(saved) : null;
        return Array.isArray(parsed) ? parsed : [];
      } catch (e) { return []; }
  });
  const [collections, setCollections] = useState(() => {
      try {
        const saved = typeof window !== 'undefined' ? localStorage.getItem('foome_collections_v7') : null;
        const parsed = saved ? JSON.parse(saved) : null;
        return Array.isArray(parsed) ? parsed : ['Geral', 'Receitas', 'Para ir'];
      } catch (e) { return ['Geral']; }
  });

  useEffect(() => {
      if (typeof window !== 'undefined') {
          localStorage.setItem('foome_posts_v7', JSON.stringify(posts));
          localStorage.setItem('foome_saved_v7', JSON.stringify(savedPosts));
          localStorage.setItem('foome_collections_v7', JSON.stringify(collections));
      }
  }, [posts, savedPosts, collections]);

  const [currentView, setCurrentView] = useState('feed'); 
  const [activeTab, setActiveTab] = useState('fit');
  const [activeTags, setActiveTags] = useState(['todos']); 
  const [activeLocation, setActiveLocation] = useState('mundo');
  const [showLocationMenu, setShowLocationMenu] = useState(false);
  const [imageIndices, setImageIndices] = useState({});
  const [commentDrafts, setCommentDrafts] = useState({});
  const [replyingToState, setReplyingToState] = useState({});
  const [showLikeAnimation, setShowLikeAnimation] = useState(null);
  const [screenWidth, setScreenWidth] = useState(375);
  const [showFooter, setShowFooter] = useState(true);
  const [headerVisible, setHeaderVisible] = useState(true);

  const [isDragging, setIsDragging] = useState(false);
  const touchRef = useRef({ startX: 0, startY: 0, isDragging: false });
  const containerRef = useRef(null);
  const feedSliderRef = useRef(null);
  const scrollRef = useRef(0);

  const [activePostComments, setActivePostComments] = useState(null);
  const [activeSavePostId, setActiveSavePostId] = useState(null); 
  const [isComposeOpen, setIsComposeOpen] = useState(false);
  const [isCameraOpen, setIsCameraOpen] = useState(false);
  const [isPlateMode, setIsPlateMode] = useState(false); 

  const [newPostText, setNewPostText] = useState('');
  const [newPostTags, setNewPostTags] = useState([]);
  const [newPostImages, setNewPostImages] = useState([]);
  const [newPostCategory, setNewPostCategory] = useState('fit');
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const fileInputRef = useRef(null);

  useEffect(() => {
    const handleResize = () => setScreenWidth(typeof window !== 'undefined' ? window.innerWidth : 375);
    window.addEventListener('resize', handleResize);
    handleResize();
    const handleScroll = () => {
      const currentY = window.scrollY;
      const diff = currentY - scrollRef.current;
      if (diff > 0 && currentY > 50) { setShowFooter(false); setHeaderVisible(false); } 
      else if (diff < 0) { setShowFooter(true); setHeaderVisible(true); }
      scrollRef.current = currentY;
    };
    window.addEventListener('scroll', handleScroll);
    return () => { window.removeEventListener('resize', handleResize); window.removeEventListener('scroll', handleScroll); };
  }, []);

  const toggleLike = (pid) => { setPosts(p => p.map(x => x.id===pid ? {...x, isLiked:!x.isLiked, likes:!x.isLiked?x.likes+1:x.likes-1} : x)); };
  const handleDoubleTap = (pid) => { setPosts(p => p.map(x => x.id===pid ? (x.isLiked ? x : {...x, isLiked: true, likes: x.likes+1}) : x)); setShowLikeAnimation(pid); setTimeout(() => setShowLikeAnimation(null), 800); };
  const onLikeComment = (pid, cid, isReply, parentId) => { setPosts(prev => prev.map(post => { if (post.id !== pid) return post; const toggle = c => ({...c, isLiked: !c.isLiked, likes: c.isLiked ? c.likes - 1 : c.likes + 1}); let newList = [...post.commentsList]; if (isReply) newList = newList.map(c => c.id === parentId ? {...c, replies: c.replies.map(r => r.id === cid ? toggle(r) : r)} : c); else newList = newList.map(c => c.id === cid ? toggle(c) : c); return {...post, commentsList: newList}; })); };
  const onReply = (pid, cid, user) => { if (!cid) setReplyingToState(prev => { const n = {...prev}; delete n[pid]; return n; }); else setReplyingToState(prev => ({...prev, [pid]: { id: cid, user }})); };
  const submitComment = (pid) => { const txt = commentDrafts[pid]; if(!txt?.trim()) return; const replyInfo = replyingToState[pid]; const newComment = { id: Date.now(), user: "Você", text: txt, likes: 0, isLiked: false, replies: [] }; setPosts(prev => prev.map(p => { if (p.id !== pid) return p; let updatedList = [...(p.commentsList || [])]; if (replyInfo) updatedList = updatedList.map(c => c.id === replyInfo.id || c.replies?.find(r => r.id === replyInfo.id) ? { ...c, replies: [...(c.replies||[]), newComment] } : c); else updatedList.push(newComment); return { ...p, commentsList: updatedList }; })); setCommentDrafts({...commentDrafts,[pid]:''}); onReply(pid, null, null); };
  const handleSavePost = (postId, collection) => { if (savedPosts.some(s => s.postId === postId && s.collection === collection)) { setSavedPosts(savedPosts.filter(s => !(s.postId === postId && s.collection === collection))); } else { setSavedPosts([...savedPosts, { postId, collection, savedAt: Date.now() }]); } setActiveSavePostId(null); };
  const createCollection = () => { const name = prompt("Nome da nova coleção:"); if (name && !collections.includes(name)) setCollections([...collections, name]); };
  const toggleFeedTag = (id) => setActiveTags(prev => id==='todos'?['todos']:(prev.includes('todos')?[id]:(prev.includes(id)?(prev.filter(x=>x!==id).length?prev.filter(x=>x!==id):['todos']):[...prev, id])));
  const filterPosts = (cat, sourcePosts = posts) => sourcePosts.filter(p => { const matchesCat = p.category === cat; const hasTags = activeTags.includes('todos') || activeTags.every(activeTag => (p.tags || []).includes(activeTag)); let matchesLoc = true; if (activeLocation === 'pais') matchesLoc = ['pais', 'cidade'].includes(p.location); if (activeLocation === 'cidade') matchesLoc = p.location === 'cidade'; return matchesCat && hasTags && matchesLoc; });
  const activeLocObj = locationsConfig.find(l => l.id === activeLocation) || locationsConfig[0];

  // --- GLOBAL SWIPE LOGIC ---
  useEffect(() => {
    if (isComposeOpen || activePostComments || activeSavePostId) return;
    const el = containerRef.current; if (!el) return;
    const handleStart = (e) => { 
        if (e.target.closest('.no-scrollbar') || e.target.closest('.carousel-no-swipe')) return; 
        touchRef.current.startX = e.touches[0].clientX; 
        touchRef.current.startY = e.touches[0].clientY; 
        touchRef.current.isDragging = false; 
        if (feedSliderRef.current) feedSliderRef.current.style.transition = 'none'; 
    };
    const handleMove = (e) => { 
        if (e.target.closest('.no-scrollbar') || e.target.closest('.carousel-no-swipe')) return; 
        const x = e.touches[0].clientX; const y = e.touches[0].clientY; const diffX = x - touchRef.current.startX; const diffY = y - touchRef.current.startY; 
        if (!touchRef.current.isDragging) { if (Math.abs(diffX) > 5 && Math.abs(diffX) > Math.abs(diffY)) { touchRef.current.isDragging = true; setIsDragging(true); } } 
        if (touchRef.current.isDragging) { if (e.cancelable) e.preventDefault(); const currentOffset = activeTab === 'fit' ? 0 : -screenWidth; let move = diffX; if ((activeTab === 'fit' && diffX > 0) || (activeTab === 'fun' && diffX < 0)) { move = diffX * 0.3; } if (feedSliderRef.current) feedSliderRef.current.style.transform = `translateX(${currentOffset + move}px)`; } 
    };
    const handleEnd = (e) => { 
        setIsDragging(false); 
        if (!touchRef.current.isDragging) { if (feedSliderRef.current) { feedSliderRef.current.style.transition = 'transform 0.3s cubic-bezier(0.2, 0.8, 0.2, 1)'; feedSliderRef.current.style.transform = `translateX(${activeTab === 'fit' ? 0 : -screenWidth}px)`; } return; } 
        const diffX = e.changedTouches[0].clientX - touchRef.current.startX; const threshold = screenWidth * 0.15; 
        if (activeTab === 'fit' && diffX > 0) { } else if (activeTab === 'fun' && diffX < 0) { } else if (activeTab === 'fit' && diffX < -threshold) setActiveTab('fun'); else if (activeTab === 'fun' && diffX > threshold) setActiveTab('fit'); 
        touchRef.current.isDragging = false; 
        if (feedSliderRef.current) { feedSliderRef.current.style.transition = 'transform 0.3s cubic-bezier(0.2, 0.8, 0.2, 1)'; feedSliderRef.current.style.transform = `translateX(${activeTab === 'fit' ? 0 : -screenWidth}px)`; } 
    };
    el.addEventListener('touchstart', handleStart, { passive: false }); el.addEventListener('touchmove', handleMove, { passive: false }); el.addEventListener('touchend', handleEnd, { passive: false }); return () => { el.removeEventListener('touchstart', handleStart); el.removeEventListener('touchmove', handleMove); el.removeEventListener('touchend', handleEnd); };
